   static void CaptureTest(){var app=new Application{ShutdownMode=ShutdownMode.OnExplicitShutdown};using(var audio=new AudioCapture()){Pump(800);Check(audio.Ready,"WASAPI demonstrated sample delivery");audio.Start();Pump(220);var stopped=audio.Stop();while(!stopped.IsCompleted)Pump(20);Check(stopped.Result.Length>2000&&stopped.Result.Length<10000,"WASAPI capture duration and tail drain");audio.Start();Pump(40);var stale=audio.Stop();audio.Cancel();audio.Start();Pump(150);var current=audio.Stop();while(!current.IsCompleted||!stale.IsCompleted)Pump(20);Eq(0,stale.Result.Length,"cancel invalidates pending tail drain");Check(current.Result.Length>1800,"old stop cannot clear new dictation");audio.Cancel();}app.Shutdown();Console.WriteLine("PASS capture hardware test");}
 [DllImport("user32.dll")]static extern uint GetClipboardSequenceNumber();
 static void InputTest(string data){var app=new Application();var panel=new StackPanel{Margin=new Thickness(24)};var box=new TextBox{Height=160,AcceptsReturn=true,TextWrapping=TextWrapping.Wrap,FontSize=18};var result=new TextBlock{Margin=new Thickness(0,15,0,15)};var button=new Button{Content="Eingabetest starten",Padding=new Thickness(20,12,20,12)};panel.Children.Add(new TextBlock{Text="Unicode-Eingabe prüfen. Die Zwischenablage wird nur auf Änderungen überwacht.",TextWrapping=TextWrapping.Wrap,Margin=new Thickness(0,0,0,15)});panel.Children.Add(box);panel.Children.Add(result);panel.Children.Add(button);var w=new Window{Title="Local Dictation Eingabetest",Width=650,Height=360,Content=panel};button.Click+=(s,e)=>{box.Clear();box.Focus();System.Windows.Input.Keyboard.Focus(box);w.Dispatcher.BeginInvoke(new Action(()=>{uint before=GetClipboardSequenceNumber();string expected="Grüße aus Köln. Straße, café und 😀.";string error;bool sent=ClipboardInserter.DeliverUnicode(expected,out error);var timer=new DispatcherTimer{Interval=TimeSpan.FromMilliseconds(350)};timer.Tick+=(a,b)=>{timer.Stop();bool passed=sent&&box.Text==expected&&before==GetClipboardSequenceNumber();result.Text=passed?"PASS: Unicode korrekt, Zwischenablage unverändert.":"FAIL: "+error+" Text="+box.Text;File.WriteAllText(Path.Combine(data,"input-result.txt"),result.Text);};timer.Start();}),DispatcherPriority.Background);};app.Run(w);}
 static void Save(FrameworkElement view,string path){view.UpdateLayout();var dpi=VisualTreeHelper.GetDpi(view);var bmp=new RenderTargetBitmap(Math.Max(1,(int)(view.ActualWidth*dpi.DpiScaleX)),Math.Max(1,(int)(view.ActualHeight*dpi.DpiScaleY)),96*dpi.DpiScaleX,96*dpi.DpiScaleY,PixelFormats.Pbgra32);bmp.Render(view);var e=new PngBitmapEncoder();e.Frames.Add(BitmapFrame.Create(bmp));using(var f=File.Create(path))e.Save(f);}
