 // Opens the history page repeatedly with the history.json in data and reports how long it takes until the page is idle.
 static void HistoryBenchmark(string data){var app=new Application{ShutdownMode=ShutdownMode.OnExplicitShutdown};var watch=System.Diagnostics.Stopwatch.StartNew();int entries=Storage.LoadHistory(data).Count;Console.WriteLine("history load ms="+watch.ElapsedMilliseconds+" entries="+entries);var w=new MainWindow(new Settings{Theme="dark"},data,x=>{},x=>{});w.Show();w.ShowDictionary();Pump(100);
   for(int run=0;run<4;run++){watch.Restart();w.ShowHistory();long build=watch.ElapsedMilliseconds;w.UpdateLayout();long layout=watch.ElapsedMilliseconds;w.Dispatcher.Invoke(()=>{},DispatcherPriority.ApplicationIdle);Console.WriteLine("history open ms="+watch.ElapsedMilliseconds+" build="+build+" layout="+layout);var search=Find<TextBox>(w).First();watch.Restart();search.Text="e";w.UpdateLayout();w.Dispatcher.Invoke(()=>{},DispatcherPriority.ApplicationIdle);Console.WriteLine("history search ms="+watch.ElapsedMilliseconds);search.Text="";w.ShowDictionary();Pump(50);}
   w.ShowHistory();w.UpdateLayout();var scroll=Find<ScrollViewer>(w).First(x=>x.ScrollableHeight>0);long slowest=0;int steps=0;while(scroll.VerticalOffset<scroll.ScrollableHeight&&steps<2000){watch.Restart();scroll.ScrollToVerticalOffset(scroll.VerticalOffset+120);w.UpdateLayout();slowest=Math.Max(slowest,watch.ElapsedMilliseconds);steps++;}
   Console.WriteLine("history scroll steps="+steps+" slowest step ms="+slowest+" end="+(int)scroll.VerticalOffset+"/"+(int)scroll.ScrollableHeight+" thumb="+(int)Find<System.Windows.Controls.Primitives.Thumb>(scroll).First().ActualHeight);scroll.ScrollToVerticalOffset(scroll.ScrollableHeight/2);Pump(100);Save(w,Path.Combine(data,"history-scrolled.png"));
   w.Close();app.Shutdown();}
 static IEnumerable<T> Find<T>(DependencyObject root) where T:DependencyObject{if(root is T result)yield return result;for(int i=0;i<VisualTreeHelper.GetChildrenCount(root);i++)foreach(var child in Find<T>(VisualTreeHelper.GetChild(root,i)))yield return child;}
